import {Led,materials} from '../../core/index.js';
import {THREE,outline,hole,solid,mesh,box,cylinder} from './geometry.js';
import {pixels} from './dimensions.js';
class PackageLed extends Led{set(state){super.set(state);this.glow.visible=false;}}
export function emitters(host){const packages=[],windows=[],dies=[],bonds=[],terminals=[],solder=[],components=[];for(const{x,y,row,col,number}of pixels){const white=materials.plastic(0xece9d9,{roughness:.58}),tin=materials.metal(0xb8baa9,{roughness:.4}),base=box(host.body,[3.5,3.5,.18],[x,y,.59],white,'A045 SK6812 '+number+' actual larger white package floor'),lipShape=outline([[-1.75,-1.75],[1.75,-1.75],[1.75,1.75],[-1.75,1.75]]);hole(lipShape,0,0,1.45);const lip=mesh(host.body,solid(lipShape,.5),white,[x,y,.68],'A045 SK6812 '+number+' actual closed white package around real resin recess');packages.push(base,lip);for(const sx of[-1,1])for(const sy of[-1,1]){terminals.push(box(host.body,[.34,.7,.2],[x+sx*1.66,y+sy*.85,.6],tin,'A045 SK6812 '+number+' real lateral metal termination'));solder.push(box(host.body,[.36,.78,.06],[x+sx*1.71,y+sy*.85,.53],tin,'A045 SK6812 '+number+' actual solder retention pad'));}
 dies.push(box(host.body,[.6,.6,.08],[x,y+.15,.73],materials.plastic(0x484333),'A045 SK6812 '+number+' fixed inner die appearance;not electronics simulation'));bonds.push(box(host.body,[.13,.8,.035],[x-.52,y-.2,.735],materials.metal(0xc7b468),'A045 SK6812 '+number+' fixed internal metal bond appearance'));
 const lens=new THREE.Mesh(cylinder(1.45,.52),new THREE.MeshStandardMaterial({color:0xe1ddc3,roughness:.25,metalness:0,transparent:true,opacity:.76}));lens.name='A045 SK6812 '+number+' independent actual resin RGB window volume';const led=host.add(new PackageLed({id:'led-'+number,label:'SK6812 '+number+' · row'+(row+1)+' col'+(col+1),mesh:lens,position:[x,y,.94],color:0xffffff,radius:1.45,glowSize:0,meta:{role:'externally-driven-visual',part:'SK6812',number,row,column:col,indexBasis:'Own hex_05 row-major1..37;reference numbers are not printed on body.',scope:'Only independent external on/color/brightness changes actual resin material;no rainbow,serial-chain,protocol,power,buffer or firmware behavior.'}}));windows.push(lens);components.push(led);}
 return{packages,windows,dies,bonds,terminals,solder,components};}
